<section class="page-heading"><p class="eyebrow">Administración</p><h1>Gestionar categorías</h1><p>Consulte nombres, cantidades y acciones. Una categoría con noticias no puede eliminarse; primero reasigne sus noticias.</p><a class="button" href="<?= e(url('category-edit')) ?>">Crear categoría</a></section>
<?php if (!$categories): ?><p class="notice">Todavía no hay categorías. Cree una para comenzar a organizar noticias.</p><?php endif ?>
<ul class="category-list"><?php foreach ($categories as $c): ?><li><div><h2><?= e($c['name']) ?></h2><p><?= e($c['total']) ?> noticias asociadas</p></div><div class="actions"><a class="button secondary" href="<?= e(url('category-edit', ['id' => $c['id']])) ?>" aria-label="<?= e('Consultar y editar categoría: ' . $c['name']) ?>">Consultar y editar</a><a class="button secondary" href="<?= e(url('category-delete', ['id' => $c['id']])) ?>" aria-label="<?= e('Revisar eliminación de categoría: ' . $c['name']) ?>">Revisar eliminación</a></div></li><?php endforeach ?></ul>
